    {binding_id=5,name="Наручники",path={"script"},old={"/me {gender:достал наручники и поднёс их к рукам задержанного|достала наручники и поднесла их к рукам задержанного}\n/do Наручники подготовлены к фиксации.\n/cuff {id}"},text="/me {gender:придерживая руку саспекта, достал наручники и аккуратно защёлкнул их на запястьях|придерживая руку саспекта, достала наручники и аккуратно защёлкнула их на запястьях}.\n/do Браслеты наручников зафиксированы и не пережимают запястья.\n/cuff {id}",label="Бинд · Наручники",prefix=""},
