}}
local function target(lib,row)
    if row.binding_id then return end -- Library binds are never part of a function-template refresh.
    local parent=lib
    if row.binding_id then
        parent=model.find(lib,row.binding_id)
        if not parent or parent.name~=row.name then return end
    end
    for i=1,#row.path-1 do parent=parent and parent[row.path[i]]end
    if type(parent)=='table'then return parent,row.path[#row.path]end
end
function M.plan(lib)
    local p={items={}}
    for _,row in ipairs(M.items)do
        local parent,key=target(lib,row)
        if parent then for _,old in ipairs(row.old)do if parent[key]==old then
            local item=model.copy(row);item.before=old
            local text=row.text
            if row.path[1]=='weapons'then text=text:gsub('{weapon}',function()return parent.name end)
            elseif row.path[1]=='taser'then text=text:gsub('{weapon}',function()return lib.taser.name end)end
            item.preview=(row.prefix or '')..text;p.items[#p.items+1]=item;break
        end end end
    end
    return p
end
function M.apply(lib,p)
    if type(p)~='table'or type(p.items)~='table'or #p.items==0 then return nil,'Нет стандартных текстов для обновления.'end
    local copy=model.copy(lib)
    for _,row in ipairs(p.items)do
        local parent,key=target(copy,row)
        if not parent or parent[key]~=row.before then return nil,'Тексты изменились после предпросмотра. Откройте обновление заново.'end
        parent[key]=row.text
    end
    return copy
end
function M.offer(s,callbacks)
    if s.dirty then return nil,'Сначала сохраните или отмените изменения открытого бинда.'end
    s:flushAutosave(callbacks,true)
    if next(s.autosaves or {})then return nil,'Сначала исправьте и сохраните изменённые настройки.'end
    local p=M.plan(s.lib)
    if #p.items==0 then return nil,'Стандартные тексты уже обновлены. Ваши собственные отыгровки оставлены как есть.'end
    s.rpPresetConfirm=p;return true
end
function M.modal(s)
    local p=s.rpPresetConfirm
    local lines={'Обновятся только показанные тексты функций вне биндов, совпадающие с прежними стандартными. Библиотека биндов не меняется.',
        'Ваши изменённые тексты, названия оружия, клавиши, команды, задержки и переключатели сохранятся. Новые тексты будут использоваться в следующих действиях. Это обновление ничего не отправляет в игровой чат.'}
    for _,row in ipairs(p.items)do
        lines[#lines+1]=row.label
        for line in(row.preview..'\n'):gmatch('(.-)\n')do lines[#lines+1]=line end
    end
    return {kind='rp_presets',token='rp-presets:'..tostring(p),title='Обновить стандартные отыгровки?',lines=lines}
end
function M.accept(s,callbacks)
    if s.dirty or next(s.autosaves or {})then return nil,'Изменения ещё не сохранены. Сначала завершите их.'end
    local lib,err=M.apply(s.lib,s.rpPresetConfirm);if not lib then return nil,err end
    local ok;ok,err=callbacks.save(lib);if not ok then return nil,err end
    s.weaponDraft=nil;s.taserDraft=nil;s.vehicleDraft=nil;s.caseDraft=nil
    s:clearPreferenceCache('weapon:');s:clearPreferenceCache('taser:');s:clearPreferenceCache('vehicle:');s:clearPreferenceCache('case:')
    s:resetBinding(s.selected);s:notify('Стандартные отыгровки обновлены. Ваши изменённые тексты сохранены.','rp_text',false,'info')
    return true
end
return M
